229	export async function setBookingStatus(opts: {
230	  businessId: string;
231	  bookingId: string;
232	  status: (typeof s.bookingStatuses)[number];
233	  actorUserId: string;
234	}): Promise<void> {
235	  const { businessId, bookingId, status, actorUserId } = opts;
236	  await db.transaction(async (tx) => {
237	    const [updated] = await tx
238	      .update(s.bookings)
239	      .set({ status })
240	      .where(and(eq(s.bookings.id, bookingId), eq(s.bookings.businessId, businessId)))
241	      .returning();
242	    if (!updated) return;
243	    await tx.insert(s.auditLog).values({
244	      businessId,
245	      actorUserId,
246	      action: `booking.${status}`,
247	      entity: "booking",
248	      entityId: bookingId,
249	    });
250	
251	    if (status !== "confirmed") {
252	      // Nobody wants a reminder for an appointment that is no longer happening.
253	      await cancelByDedupeKey(tx, `booking.reminder:${bookingId}`);
254	    }
255	    if (status === "cancelled") {
256	      await enqueue(tx, {
257	        businessId,
258	        topic: "booking.cancelled",
259	        payload: { bookingId },
260	        dedupeKey: `booking.cancelled:${bookingId}`,
261	      });
262	      // The time is free again — offer it down the waitlist before it goes
263	      // back into public stock. Enqueued rather than called directly: keeps
264	      // this transaction pure SQL, and keeps booking.ts free of a dependency
265	      // on waitlist.ts (which already depends on this file).
266	      await enqueue(tx, {
267	        businessId,
268	        topic: "waitlist.slot_freed",
269	        payload: {
270	          staffId: updated.staffId,
271	          serviceId: updated.serviceId,
272	          startMs: updated.startAt.getTime(),
273	          endMs: updated.endAt.getTime(),
274	        },
275	        dedupeKey: `waitlist.freed:${bookingId}`,
276	      });
277	    }
278	  });
279	  await publishCalendar(businessId, { type: "booking.updated", bookingId });
280	}
281	
282	export async function staffForService(businessId: string, serviceId: string) {
283	  const links = await db
284	    .select({ staffId: s.staffServices.staffId })
285	    .from(s.staffServices)
286	    .where(eq(s.staffServices.serviceId, serviceId));
287	  if (links.length === 0) return [];
288	  return db
289	    .select({ id: s.staff.id, name: s.staff.name })
290	    .from(s.staff)
291	    .where(
292	      and(
293	        eq(s.staff.businessId, businessId),
294	        eq(s.staff.isActive, true),
295	        inArray(s.staff.id, links.map((l) => l.staffId)),
296	      ),
297	    );
298	}
