1	import "server-only";
2	import { randomBytes } from "node:crypto";
3	import { and, asc, eq, isNull, or } from "drizzle-orm";
4	import { db, schema as s } from "@/db";
5	import { createBooking, createHold, publishCalendar } from "./booking";
6	import { enqueue } from "./outbox";
7	import { redis } from "./redis";
8	
9	/** How long a client has to accept a freed slot before it moves down the queue. */
10	export const OFFER_TTL_SEC = 15 * 60;
11	
12	export type JoinResult = { entryId: string };
13	
14	export async function joinWaitlist(opts: {
15	  businessId: string;
16	  serviceId: string;
17	  staffId?: string | null;
18	  dateISO: string;
19	  client: { name: string; phone: string };
20	}): Promise<JoinResult> {
21	  const { businessId, serviceId, staffId, dateISO, client } = opts;
22	
23	  return db.transaction(async (tx) => {
24	    const [existing] = await tx
25	      .select()
26	      .from(s.clients)
27	      .where(and(eq(s.clients.businessId, businessId), eq(s.clients.phone, client.phone)));
28	    const clientRow =
29	      existing ??
30	      (
31	        await tx
32	          .insert(s.clients)
33	          .values({ businessId, name: client.name, phone: client.phone })
34	          .returning()
35	      )[0];
36	
37	    const [entry] = await tx
38	      .insert(s.waitlistEntries)
39	      .values({
40	        businessId,
41	        serviceId,
42	        staffId: staffId ?? null,
43	        clientId: clientRow.id,
44	        dateISO,
45	      })
46	      .returning();
47	
48	    return { entryId: entry.id };
49	  });
50	}
51	
52	type FreedSlot = { staffId: string; serviceId: string; startMs: number; endMs: number };
53	
54	/**
55	 * Offers a freed slot to the longest-waiting eligible client.
56	 *
57	 * Eligibility: same service, same local day, and either no master preference
58	 * or a preference for the one who freed up. Returns the entry that was offered,
59	 * or null when nobody is waiting (the slot simply returns to public stock).
60	 */
61	export async function offerFreedSlot(businessId: string, slot: FreedSlot): Promise<string | null> {
62	  const [business] = await db.select().from(s.businesses).where(eq(s.businesses.id, businessId));
63	  if (!business) return null;
64	
65	  const dateISO = new Intl.DateTimeFormat("en-CA", { timeZone: business.timezone }).format(
66	    slot.startMs,
67	  );
68	
69	  const [entry] = await db
70	    .select()
71	    .from(s.waitlistEntries)
72	    .where(
73	      and(
74	        eq(s.waitlistEntries.businessId, businessId),
75	        eq(s.waitlistEntries.serviceId, slot.serviceId),
76	        eq(s.waitlistEntries.dateISO, dateISO),
77	        eq(s.waitlistEntries.status, "waiting"),
78	        or(isNull(s.waitlistEntries.staffId), eq(s.waitlistEntries.staffId, slot.staffId)),
79	      ),
80	    )
81	    .orderBy(asc(s.waitlistEntries.createdAt))
82	    .limit(1);
83	
84	  if (!entry) return null;
85	
86	  // Reserve the slot for them specifically, so a walk-in cannot take it out
87	  // from under an outstanding offer.
88	  const token = randomBytes(16).toString("hex");
89	  const held = await createHold(
90	    slot.staffId,
91	    { startMs: slot.startMs, endMs: slot.endMs },
92	    OFFER_TTL_SEC,
93	  );
94	  if (!held) return null; // someone booked it first; nothing to offer
95	
96	  const expiresAt = new Date(Date.now() + OFFER_TTL_SEC * 1000);
97	
98	  await db.transaction(async (tx) => {
99	    await tx
100	      .update(s.waitlistEntries)
101	      .set({
102	        status: "offered",
103	        offerToken: token,
104	        offerHoldToken: held,
105	        offerSlotStartAt: new Date(slot.startMs),
106	        offerSlotEndAt: new Date(slot.endMs),
107	        offerExpiresAt: expiresAt,
108	        offerStaffId: slot.staffId,
109	      })
110	      .where(eq(s.waitlistEntries.id, entry.id));
111	
112	    await tx.insert(s.auditLog).values({
113	      businessId,
114	      action: "waitlist.offered",
115	      entity: "waitlist_entry",
116	      entityId: entry.id,
117	      meta: { staffId: slot.staffId, startMs: slot.startMs },
118	    });
119	
120	    await enqueue(tx, {
121	      businessId,
122	      topic: "waitlist.offer",
123	      payload: { entryId: entry.id },
124	      dedupeKey: `waitlist.offer:${entry.id}:${slot.startMs}`,
125	    });
126	
127	    // Self-scheduled deadline: if they have not accepted by then, the offer
128	    // lapses and the slot is announced again for the next person in line.
129	    await enqueue(tx, {
130	      businessId,
131	      topic: "waitlist.offer_expired",
132	      payload: { entryId: entry.id },
133	      dedupeKey: `waitlist.expire:${entry.id}:${slot.startMs}`,
134	      availableAt: expiresAt,
135	    });
136	  });
137	
138	  return entry.id;
139	}
140	
141	/** Called by the worker when an offer's deadline passes. */
142	export async function expireOffer(entryId: string): Promise<void> {
143	  const [entry] = await db
144	    .select()
145	    .from(s.waitlistEntries)
146	    .where(eq(s.waitlistEntries.id, entryId));
147	  if (!entry || entry.status !== "offered") return; // accepted or cancelled already
148	
149	  const slot = {
150	    staffId: entry.offerStaffId!,
151	    serviceId: entry.serviceId,
152	    startMs: entry.offerSlotStartAt!.getTime(),
153	    endMs: entry.offerSlotEndAt!.getTime(),
154	  };
155	
156	  await db.transaction(async (tx) => {
157	    await tx
158	      .update(s.waitlistEntries)
159	      .set({
160	        status: "expired",
161	        offerToken: null,
162	        offerExpiresAt: null,
163	      })
164	      .where(eq(s.waitlistEntries.id, entryId));
165	
166	    // Hand the slot to whoever is next.
167	    await enqueue(tx, {
168	      businessId: entry.businessId,
169	      topic: "waitlist.slot_freed",
170	      payload: slot,
171	      dedupeKey: `waitlist.refree:${entryId}:${slot.startMs}`,
172	    });
173	  });
174	
175	  await releaseHold(slot.staffId, slot.startMs);
176	}
177	
178	async function releaseHold(staffId: string, startMs: number): Promise<void> {
179	  await redis().del(`hold:${staffId}:${startMs}`);
180	}
181	
182	export type AcceptResult =
183	  | { ok: true; bookingId: string }
184	  | { ok: false; error: "not_found" | "expired" | "slot_taken" };
185	
186	/** Turns an outstanding offer into a real booking. */
187	export async function acceptOffer(token: string): Promise<AcceptResult> {
188	  const [entry] = await db
189	    .select()
190	    .from(s.waitlistEntries)
191	    .where(eq(s.waitlistEntries.offerToken, token));
192	  if (!entry) return { ok: false, error: "not_found" };
193	  if (entry.status !== "offered") return { ok: false, error: "expired" };
194	  if (!entry.offerExpiresAt || entry.offerExpiresAt.getTime() < Date.now()) {
195	    return { ok: false, error: "expired" };
196	  }
197	
198	  const [client] = await db.select().from(s.clients).where(eq(s.clients.id, entry.clientId));
199	  const holdToken = entry.offerHoldToken;
200	  if (!holdToken) return { ok: false, error: "expired" };
201	
202	  const result = await createBooking({
203	    businessId: entry.businessId,
204	    staffId: entry.offerStaffId!,
205	    serviceId: entry.serviceId,
206	    slot: {
207	      startMs: entry.offerSlotStartAt!.getTime(),
208	      endMs: entry.offerSlotEndAt!.getTime(),
209	    },
210	    holdToken,
211	    client: { name: client.name, phone: client.phone },
212	  });
213	
214	  if (!result.ok) return { ok: false, error: "slot_taken" };
215	
216	  await db
217	    .update(s.waitlistEntries)
218	    .set({ status: "booked", offerToken: null, offerHoldToken: null })
219	    .where(eq(s.waitlistEntries.id, entry.id));
220	  await publishCalendar(entry.businessId, { type: "booking.created", bookingId: result.bookingId });
221	
222	  return { ok: true, bookingId: result.bookingId };
223	}
