1	import { NextRequest, NextResponse } from "next/server";
2	import { z } from "zod";
3	import { createBooking } from "@/lib/booking";
4	import { businessBySlug, clientIp } from "@/lib/public";
5	import { rateLimit } from "@/lib/ratelimit";
6	
7	const body = z.object({
8	  serviceId: z.uuid(),
9	  staffId: z.uuid(),
10	  startMs: z.number().int(),
11	  endMs: z.number().int(),
12	  holdToken: z.string().min(16),
13	  name: z.string().trim().min(1).max(100),
14	  phone: z.string().trim().regex(/^\+?\d{10,15}$/),
15	});
16	
17	export async function POST(req: NextRequest, ctx: { params: Promise<{ slug: string }> }) {
18	  const { slug } = await ctx.params;
19	  if (!(await rateLimit(`book:${await clientIp()}`, 10, 60))) {
20	    return NextResponse.json({ error: "rate_limited" }, { status: 429 });
21	  }
22	  const parsed = body.safeParse(await req.json().catch(() => null));
23	  if (!parsed.success) return NextResponse.json({ error: "bad_request" }, { status: 400 });
24	  const biz = await businessBySlug(slug);
25	  if (!biz) return NextResponse.json({ error: "not_found" }, { status: 404 });
26	
27	  const { serviceId, staffId, startMs, endMs, holdToken, name, phone } = parsed.data;
28	  const result = await createBooking({
29	    businessId: biz.id,
30	    staffId,
31	    serviceId,
32	    slot: { startMs, endMs },
33	    holdToken,
34	    client: { name, phone },
35	  });
36	  if (!result.ok) {
37	    return NextResponse.json({ error: result.error }, { status: 409 });
38	  }
39	  return NextResponse.json({ bookingId: result.bookingId });
40	}
