1	import { NextRequest, NextResponse } from "next/server";
2	import { z } from "zod";
3	import { businessBySlug, clientIp } from "@/lib/public";
4	import { rateLimit } from "@/lib/ratelimit";
5	import { joinWaitlist } from "@/lib/waitlist";
6	
7	const body = z.object({
8	  serviceId: z.uuid(),
9	  staffId: z.uuid().nullable().optional(),
10	  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
11	  name: z.string().trim().min(1).max(100),
12	  phone: z.string().trim().regex(/^\+?\d{10,15}$/),
13	});
14	
15	export async function POST(req: NextRequest, ctx: { params: Promise<{ slug: string }> }) {
16	  const { slug } = await ctx.params;
17	  if (!(await rateLimit(`waitlist:${await clientIp()}`, 10, 60))) {
18	    return NextResponse.json({ error: "rate_limited" }, { status: 429 });
19	  }
20	  const parsed = body.safeParse(await req.json().catch(() => null));
21	  if (!parsed.success) return NextResponse.json({ error: "bad_request" }, { status: 400 });
22	
23	  const biz = await businessBySlug(slug);
24	  if (!biz) return NextResponse.json({ error: "not_found" }, { status: 404 });
25	
26	  const { entryId } = await joinWaitlist({
27	    businessId: biz.id,
28	    serviceId: parsed.data.serviceId,
29	    staffId: parsed.data.staffId ?? null,
30	    dateISO: parsed.data.date,
31	    client: { name: parsed.data.name, phone: parsed.data.phone },
32	  });
33	  return NextResponse.json({ entryId });
