1	import { NextRequest, NextResponse } from "next/server";
2	import { z } from "zod";
3	import { createHold, getAvailability } from "@/lib/booking";
4	import { businessBySlug, clientIp } from "@/lib/public";
5	import { rateLimit } from "@/lib/ratelimit";
6	
7	const body = z.object({
8	  serviceId: z.uuid(),
9	  staffId: z.uuid(),
10	  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
11	  startMs: z.number().int(),
12	});
