14	// Places a short-lived Redis hold on a slot (like a cart reservation)
15	// so the client can fill in contact details without losing the time.
16	export async function POST(req: NextRequest, ctx: { params: Promise<{ slug: string }> }) {
17	  const { slug } = await ctx.params;
18	  if (!(await rateLimit(`hold:${await clientIp()}`, 20, 60))) {
19	    return NextResponse.json({ error: "rate_limited" }, { status: 429 });
20	  }
21	  const parsed = body.safeParse(await req.json().catch(() => null));
22	  if (!parsed.success) return NextResponse.json({ error: "bad_request" }, { status: 400 });
23	  const biz = await businessBySlug(slug);
24	  if (!biz) return NextResponse.json({ error: "not_found" }, { status: 404 });
25	
26	  // The slot must be genuinely available right now (endMs comes from the
27	  // server-computed grid, never from the client).
28	  const slots = await getAvailability({
29	    businessId: biz.id,
30	    timeZone: biz.timezone,
31	    staffId: parsed.data.staffId,
32	    serviceId: parsed.data.serviceId,
33	    dateISO: parsed.data.date,
34	  });
35	  const slot = slots.find((sl) => sl.startMs === parsed.data.startMs);
36	  if (!slot) return NextResponse.json({ error: "slot_unavailable" }, { status: 409 });
37	
38	  const token = await createHold(parsed.data.staffId, slot, biz.holdTtlSec);
39	  if (!token) return NextResponse.json({ error: "slot_unavailable" }, { status: 409 });
40	  return NextResponse.json({ holdToken: token, expiresInSec: biz.holdTtlSec, slot });
41	}
