7	// Deterministic demo dataset: one salon in Almaty, 3 masters, 5 services,
8	// clients and a spread of past/future bookings so the reports page has data.
9	async function main() {
10	  const pool = new Pool({ connectionString: process.env.DATABASE_URL });
11	  const db = drizzle(pool, { schema: s });
12	
13	  // Idempotent: wipe and re-seed.
14	  await db.delete(s.messageLog);
15	  await db.delete(s.outbox);
16	  await db.delete(s.waitlistEntries);
17	  await db.delete(s.auditLog);
18	  await db.delete(s.bookings);
19	  await db.delete(s.clients);
20	  await db.delete(s.staffServices);
21	  await db.delete(s.staffHours);
22	  await db.delete(s.services);
23	  await db.delete(s.staff);
24	  await db.delete(s.businessHours);
25	  await db.delete(s.users);
26	  await db.delete(s.businesses);
27	
28	  const [biz] = await db
29	    .insert(s.businesses)
30	    .values({ slug: "aruzhan", name: "Aruzhan Beauty", timezone: "Asia/Almaty" })
31	    .returning();
32	
33	  // Tue–Sun 10:00–20:00, Monday closed
34	  await db.insert(s.businessHours).values(
35	    [2, 3, 4, 5, 6, 7].map((weekday) => ({
36	      businessId: biz.id,
37	      weekday,
38	      openTime: "10:00",
39	      closeTime: "20:00",
40	    })),
41	  );
42	
43	  const passwordHash = await bcrypt.hash("kezek-demo", 10);
44	  await db.insert(s.users).values({
45	    email: "owner@kezek.dev",
46	    passwordHash,
47	    name: "Aruzhan",
48	    role: "owner",
49	    businessId: biz.id,
50	  });
51	
52	  const masters = await db
53	    .insert(s.staff)
54	    .values([
55	      { businessId: biz.id, name: "Dana" },
56	      { businessId: biz.id, name: "Madina" },
57	      { businessId: biz.id, name: "Aliya" },
58	    ])
59	    .returning();
60	
61	  // Aliya works short days
62	  await db.insert(s.staffHours).values(
63	    [2, 3, 4, 5, 6].map((weekday) => ({
64	      staffId: masters[2].id,
65	      weekday,
66	      startTime: "12:00",
67	      endTime: "18:00",
68	    })),
69	  );
70	
71	  const svc = await db
72	    .insert(s.services)
73	    .values([
74	      { businessId: biz.id, name: "Women's haircut", durationMin: 60, priceKzt: 8000 },
75	      { businessId: biz.id, name: "Men's haircut", durationMin: 45, priceKzt: 5000 },
76	      { businessId: biz.id, name: "Hair coloring", durationMin: 120, priceKzt: 25000 },
77	      { businessId: biz.id, name: "Manicure", durationMin: 90, priceKzt: 12000 },
78	      { businessId: biz.id, name: "Blow-dry", durationMin: 40, priceKzt: 6000 },
79	    ])
80	    .returning();
81	
82	  await db.insert(s.staffServices).values([
83	    { staffId: masters[0].id, serviceId: svc[0].id },
84	    { staffId: masters[0].id, serviceId: svc[1].id },
85	    { staffId: masters[0].id, serviceId: svc[4].id },
86	    { staffId: masters[1].id, serviceId: svc[0].id },
87	    { staffId: masters[1].id, serviceId: svc[2].id },
88	    { staffId: masters[1].id, serviceId: svc[4].id },
89	    { staffId: masters[2].id, serviceId: svc[3].id },
90	  ]);
91	
92	  const names = [
93	    ["Aida", "+77011234501"],
94	    ["Zhanna", "+77011234502"],
95	    ["Karina", "+77011234503"],
96	    ["Saule", "+77011234504"],
97	    ["Inkar", "+77011234505"],
98	    ["Tomiris", "+77011234506"],
99	    ["Assel", "+77011234507"],
100	    ["Diana", "+77011234508"],
101	  ] as const;
102	  const cls = await db
103	    .insert(s.clients)
104	    .values(names.map(([name, phone]) => ({ businessId: biz.id, name, phone })))
105	    .returning();
106	
107	  // Bookings from 3 weeks ago through 3 days ahead, so a fresh clone opens on
108	  // a day that actually has something in it. Past ones are settled
109	  // (completed / the occasional no-show), future ones are still confirmed.
110	  // All times UTC; Almaty is UTC+5, so 05:00Z = 10:00 local.
111	  const day = 24 * 3600 * 1000;
112	  const now = Date.now();
113	  const rows: (typeof s.bookings.$inferInsert)[] = [];
114	  let i = 0;
115	  for (let d = 21; d >= -3; d--) {
116	    const base = new Date(now - d * day);
117	    if (base.getUTCDay() === 1) continue; // Monday closed
118	    // 2-4 bookings per day, alternating masters/services
119	    const perDay = 2 + ((Math.abs(d) * 7) % 3);
120	    for (let k = 0; k < perDay; k++) {
121	      const master = masters[(i + k) % 2]; // Dana/Madina work full days
122	      const service = svc.filter((v, idx) => [0, 1, 2, 4].includes(idx))[(i + k) % 4];
123	      const startHourUtc = 5 + k * 3; // 10:00, 13:00, 16:00, 19:00 local
124	      const start = new Date(base);
125	      start.setUTCHours(startHourUtc, 0, 0, 0);
126	      const end = new Date(start.getTime() + service.durationMin * 60000);
127	      const isPast = end.getTime() < now;
128	      const noShow = isPast && (i + k) % 9 === 0;
129	      rows.push({
130	        businessId: biz.id,
131	        staffId: master.id,
132	        serviceId: service.id,
133	        clientId: cls[(i + k) % cls.length].id,
134	        startAt: start,
135	        endAt: end,
136	        status: noShow ? "no_show" : isPast ? "completed" : "confirmed",
137	        priceKzt: service.priceKzt,
138	      });
139	      i++;
140	    }
141	  }
142	  const inserted = await db.insert(s.bookings).values(rows).returning();
143	
144	  // Queue the messages the upcoming bookings would have produced, so the
145	  // notifications page has something to show and `pnpm worker` has work to do.
146	  const upcoming = inserted.filter((b) => b.status === "confirmed");
147	  if (upcoming.length > 0) {
148	    await db.insert(s.outbox).values(
149	      upcoming.flatMap((b) => [
150	        {
151	          businessId: biz.id,
152	          topic: "booking.confirmed",
153	          payload: { bookingId: b.id },
154	          dedupeKey: `booking.confirmed:${b.id}`,
155	        },
156	        {
157	          businessId: biz.id,
158	          topic: "booking.reminder",
159	          payload: { bookingId: b.id },
160	          dedupeKey: `booking.reminder:${b.id}`,
161	          availableAt: new Date(b.startAt.getTime() - 24 * 3600_000),
162	        },
163	      ]),
164	    );
165	  }
166	
167	  console.log(`Seeded: business=${biz.slug}, staff=${masters.length}, services=${svc.length}, clients=${cls.length}, bookings=${rows.length}`);
168	  console.log("Admin login: owner@kezek.dev / kezek-demo");
169	  await pool.end();
170	}
171	
172	main().catch((e) => {
173	  console.error(e);
174	  process.exit(1);
175	});
